import { execFileSync } from "node:child_process";
import { chmodSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Review } from "@viva/contracts";
import { allowsPush } from "@viva/engine";

const PORT = process.env.VIVA_PORT ?? "4317";
const API = `http://127.0.0.1:${PORT}/v1`;
const WEB = process.env.VIVA_WEB ?? "http://localhost:5173";
const POLL_MS = 1000;
const EXAM_TIMEOUT_MS = 10 * 60 * 1000;
const MARKER = "# viva gate";

const VIVA_ROOT = resolve(fileURLToPath(new URL("../../..", import.meta.url))).replaceAll("\\", "/");
/** The repo being pushed. Set by the hook, as pnpm --dir changes the working directory. */
const REPO = process.env.VIVA_REPO ?? process.cwd();

const git = (...args: string[]) => execFileSync("git", args, { cwd: REPO, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();

function pushBase(): string {
  for (const ref of ["@{upstream}", "origin/main", "main"]) {
    try {
      return git("merge-base", ref, "HEAD");
    } catch {
      // Try the next candidate.
    }
  }
  return "HEAD~1";
}

async function gate(): Promise<number> {
  const request = {
    repoPath: git("rev-parse", "--show-toplevel"),
    base: pushBase(),
    head: git("rev-parse", "HEAD"),
    person: git("config", "user.name"),
  };

  let review: Review;
  try {
    const response = await fetch(`${API}/reviews`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(request),
    });
    if (!response.ok) throw new Error(`vivad returned ${response.status}`);
    review = Review.parse(await response.json());
  } catch (error) {
    // Fail open: a broken or absent daemon must never stop a push.
    console.warn(`viva: skipped, daemon unavailable (${(error as Error).message})`);
    return 0;
  }

  if (review.stage === "awaiting-exam") {
    console.log(`viva: this push needs a viva: ${WEB}/?review=${review.id}`);
    const deadline = Date.now() + EXAM_TIMEOUT_MS;
    while (review.stage !== "done" && Date.now() < deadline) {
      await new Promise((resolve) => setTimeout(resolve, POLL_MS));
      review = Review.parse(await (await fetch(`${API}/reviews/${review.id}`)).json());
    }
  }

  if (!review.gate) {
    console.error("viva: exam timed out, push blocked");
    return 1;
  }
  console.log(`viva: ${review.gate.verdict} (${review.gate.reason})`);
  return allowsPush(review.gate) ? 0 : 1;
}

/** Appends to the hook, as core.hooksPath would bypass Entire's hooks. */
function installHook(): number {
  const path = resolve(REPO, git("rev-parse", "--git-path", "hooks"), "pre-push");
  const existing = existsSync(path) ? readFileSync(path, "utf8") : "#!/bin/sh\n";
  if (existing.includes(MARKER)) {
    console.log("viva: hook already installed");
    return 0;
  }
  writeFileSync(path, `${existing.trimEnd()}\n\n${MARKER}\nVIVA_REPO="$(pwd)" pnpm --silent --dir "${VIVA_ROOT}" viva gate || exit $?\n`);
  chmodSync(path, 0o755);
  console.log(`viva: installed ${path}`);
  return 0;
}

const [command, sub] = process.argv.slice(2);
if (command === "gate") process.exit(await gate());
if (command === "hook" && sub === "install") process.exit(installHook());
console.log("usage: viva gate | viva hook install");
process.exit(command ? 1 : 0);
/**
 * The contract between the engine, the daemon and the UI.
 * Change this first, then update fixtures/mock so the frontend keeps working.
 */
import { z } from "zod";

/** Mabel-style verdicts, ordered from worst to best. */
export const VERDICTS = ["reject", "defer", "approve", "endorse"] as const;
export const Verdict = z.enum(VERDICTS);
export type Verdict = z.infer<typeof Verdict>;

/** Worst wins: any reject blocks, however many approvals surround it. */
export function worstVerdict(verdicts: readonly Verdict[]): Verdict {
  const rank = (v: Verdict) => VERDICTS.indexOf(v);
  return verdicts.reduce<Verdict>((w, v) => (rank(v) < rank(w) ? v : w), "endorse");
}

/** Where a decision came from, relative to what the human asked for. */
export const Origin = z.enum(["requested", "inferred", "silent"]);
export type Origin = z.infer<typeof Origin>;

export const CodeLocation = z.object({
  file: z.string(),
  lines: z.tuple([z.number().int().positive(), z.number().int().positive()]),
});
export type CodeLocation = z.infer<typeof CodeLocation>;

/** One decision found in a change. Produced by a check, ranked by risk. */
export const Claim = z.object({
  id: z.string(),
  check: z.string(),
  summary: z.string(),
  origin: Origin,
  symbols: z.array(z.string()),
  location: CodeLocation,
  evidence: z.string(),
});
export type Claim = z.infer<typeof Claim>;

export const RiskInputs = z.object({
  blastRadius: z.number().min(0),
  originWeight: z.number().min(0),
  untested: z.number().min(0).max(1),
  mastery: z.number().min(0).max(1),
});
export type RiskInputs = z.infer<typeof RiskInputs>;

export const RankedClaim = Claim.extend({ risk: z.number().min(0), inputs: RiskInputs });
export type RankedClaim = z.infer<typeof RankedClaim>;

/** Model output for a check. Parsed before use, never trusted as prose. */
export const CheckResult = z.object({ claims: z.array(Claim.omit({ id: true, check: true })) });
export type CheckResult = z.infer<typeof CheckResult>;

export const Question = z.object({
  id: z.string(),
  claimId: z.string(),
  ask: z.string(),
  mustMention: z.array(z.string()).min(1),
  followUpIfVague: z.string(),
  location: CodeLocation,
});
export type Question = z.infer<typeof Question>;

export const ExamPlan = z.object({ questions: z.array(Question).max(3) });
export type ExamPlan = z.infer<typeof ExamPlan>;

export const AnswerMode = z.enum(["voice", "typed"]);
export const Answer = z.object({
  questionId: z.string(),
  transcript: z.string(),
  mode: AnswerMode,
});
export type Answer = z.infer<typeof Answer>;

/** The grader sees the transcript and rubric only. Accent and fluency cannot reach it. */
export const Grade = z.object({
  questionId: z.string(),
  verdict: Verdict,
  score: z.number().min(0).max(1),
  missing: z.array(z.string()),
});
export type Grade = z.infer<typeof Grade>;

export const ReviewStage = z.enum([
  "collecting",
  "prechecks",
  "injection-scan",
  "checks",
  "planning",
  "awaiting-exam",
  "grading",
  "done",
]);
export type ReviewStage = z.infer<typeof ReviewStage>;

/** Why the gate decided what it did. Safe to log: it holds no diff or prose. */
export const GateReason = z.enum([
  "docs-only",
  "low-risk",
  "earned-trust",
  "too-large",
  "injection-suspected",
  "viva-config-changed",
  "exam-passed",
  "exam-failed",
  "skipped-with-debt",
  "pipeline-error",
]);
export type GateReason = z.infer<typeof GateReason>;

export const Gate = z.object({
  verdict: Verdict,
  reason: GateReason,
  /** False for hard gates, which config and "skip with debt" cannot bypass. */
  skippable: z.boolean(),
});
export type Gate = z.infer<typeof Gate>;

export const ReviewRequest = z.object({
  repoPath: z.string(),
  base: z.string(),
  head: z.string(),
  person: z.string(),
  intent: z.string().optional(),
});
export type ReviewRequest = z.infer<typeof ReviewRequest>;

export const Usage = z.object({
  inputTokens: z.number().int().nonnegative(),
  outputTokens: z.number().int().nonnegative(),
  llmCalls: z.number().int().nonnegative(),
});
export type Usage = z.infer<typeof Usage>;

export const Review = z.object({
  id: z.string(),
  request: ReviewRequest,
  stage: ReviewStage,
  claims: z.array(RankedClaim),
  plan: ExamPlan.nullable(),
  grades: z.array(Grade),
  gate: Gate.nullable(),
  usage: Usage,
  startedAt: z.string(),
  finishedAt: z.string().nullable(),
});
export type Review = z.infer<typeof Review>;

/**
 * One line of the ledger. Mirrors Mabel's data boundary: scores and hashes
 * leave the review, while diffs, transcripts and model output do not.
 */
export const Attestation = z.object({
  person: z.string(),
  symbol: z.string(),
  file: z.string(),
  codeHash: z.string(),
  score: z.number().min(0).max(1),
  at: z.string(),
  reviewId: z.string(),
});
export type Attestation = z.infer<typeof Attestation>;

export const FogNode = z.object({
  id: z.string(),
  file: z.string(),
  symbol: z.string().nullable(),
  size: z.number().nonnegative(),
  blastRadius: z.number().nonnegative(),
  /** 0 is fully understood, 1 is understood by nobody. */
  fog: z.number().min(0).max(1),
  knownBy: z.array(z.object({ person: z.string(), mastery: z.number().min(0).max(1) })),
});
export type FogNode = z.infer<typeof FogNode>;

export const FogMap = z.object({
  generatedAt: z.string(),
  debt: z.number().nonnegative(),
  nodes: z.array(FogNode),
});
export type FogMap = z.infer<typeof FogMap>;
import { zodToJsonSchema } from "zod-to-json-schema";
import type { LlmProvider, LlmRequest, LlmResult } from "./provider.js";

/** Gemini rejects tuple schemas, where `items` is an array, so flatten them. */
export function toGeminiSchema(schema: unknown): unknown {
  if (Array.isArray(schema)) return schema.map(toGeminiSchema);
  if (typeof schema !== "object" || schema === null) return schema;
  const copy: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(schema)) {
    if (key === "$schema") continue;
    copy[key] = key === "items" && Array.isArray(value) ? toGeminiSchema(value[0]) : toGeminiSchema(value);
  }
  return copy;
}

const RETRYABLE = new Set([429, 500, 502, 503, 504]);
const ATTEMPTS_PER_MODEL = 2;
const REQUEST_TIMEOUT_MS = 12_000;

export class GeminiProvider implements LlmProvider {
  readonly id = "gemini";

  constructor(
    private readonly apiKey: string,
    private readonly model: string,
    private readonly fallbackModel?: string,
    private readonly backoffMs = 800,
  ) {}

  /** Capacity errors are common, so retry, then fall back to the second model. */
  private async request(body: string): Promise<Response> {
    const models = this.fallbackModel ? [this.model, this.fallbackModel] : [this.model];
    let last: Response | undefined;
    let failure: unknown;
    for (const model of models) {
      for (let attempt = 0; attempt < ATTEMPTS_PER_MODEL; attempt += 1) {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
        try {
          last = await fetch(url, {
            method: "POST",
            headers: { "content-type": "application/json", "x-goog-api-key": this.apiKey },
            body,
            signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
          });
          if (!RETRYABLE.has(last.status)) return last;
        } catch (error) {
          failure = error;
        }
        await new Promise((resolve) => setTimeout(resolve, this.backoffMs * (attempt + 1)));
      }
    }
    if (last) return last;
    throw failure;
  }

  async complete<T>({ system, user, schema }: LlmRequest<T>): Promise<LlmResult<T>> {
    const response = await this.request(
      JSON.stringify({
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: "user", parts: [{ text: user }] }],
        generationConfig: {
          responseMimeType: "application/json",
          responseJsonSchema: toGeminiSchema(zodToJsonSchema(schema, { $refStrategy: "none" })),
        },
      }),
    );
    if (!response.ok) {
      throw new Error(`Gemini returned ${response.status}: ${(await response.text()).slice(0, 300)}`);
    }
    const body = (await response.json()) as {
      candidates?: { content?: { parts?: { text?: string }[] } }[];
      usageMetadata?: { promptTokenCount?: number; candidatesTokenCount?: number };
    };
    const text = body.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) throw new Error("Gemini returned no content");
    return {
      value: schema.parse(JSON.parse(text)),
      inputTokens: body.usageMetadata?.promptTokenCount ?? 0,
      outputTokens: body.usageMetadata?.candidatesTokenCount ?? 0,
    };
  }
}
import type { CheckResult, ExamPlan, Grade } from "@viva/contracts";
import type { LlmProvider, LlmRequest, LlmResult } from "./provider.js";

const RISKY = /\b(charge|delete|drop|timeout|retry|idempot\w*|auth\w*|token|lock|await|or|not|null)\b/i;

function checkResponse(user: string): CheckResult {
  const claims: CheckResult["claims"] = [];
  const intent = /<untrusted name="intent">\n([\s\S]*?)\n<\/untrusted>/.exec(user)?.[1] ?? "";
  let file = "unknown";
  let line = 1;
  for (const raw of user.split("\n")) {
    const header = /^\+\+\+ b\/(.+)$/.exec(raw);
    if (header) file = header[1] ?? file;
    const hunk = /^@@ .* \+(\d+)/.exec(raw);
    if (hunk) line = Number(hunk[1]);
    if (raw.startsWith("+") && !raw.startsWith("+++") && RISKY.test(raw)) {
      const word = RISKY.exec(raw)?.[0] ?? "";
      claims.push({
        summary: `Changed logic around "${word}"`,
        origin: intent.toLowerCase().includes(word.toLowerCase()) ? "requested" : "silent",
        symbols: [],
        location: { file, lines: [line, line] },
        evidence: "Mock heuristic: risky keyword on an added line",
      });
      break;
    }
    if (!raw.startsWith("-")) line += 1;
  }
  return { claims };
}

function planResponse(user: string): ExamPlan {
  const claims = JSON.parse(/<untrusted name="claims">\n([\s\S]*?)\n<\/untrusted>/.exec(user)?.[1] ?? "[]");
  return {
    questions: claims.slice(0, 3).map((c: { id: string; summary: string; location: ExamPlan["questions"][number]["location"] }, i: number) => ({
      id: `q${i + 1}`,
      claimId: c.id,
      ask: `What behaviour changes because of this: ${c.summary}?`,
      mustMention: ["behaviour"],
      followUpIfVague: "Walk me through what happens at runtime.",
      location: c.location,
    })),
  };
}

function gradeResponse(user: string): { grades: Grade[] } {
  const answer = /<untrusted name="answer">\n([\s\S]*?)\n<\/untrusted>/.exec(user)?.[1] ?? "";
  const id = /question_id: (\S+)/.exec(user)?.[1] ?? "q1";
  const mustMention: string[] = JSON.parse(/must_mention: (\[.*\])/.exec(user)?.[1] ?? "[]");
  const missing = mustMention.filter((m) => !answer.toLowerCase().includes(m.toLowerCase()));
  const score = mustMention.length ? 1 - missing.length / mustMention.length : 0;
  return { grades: [{ questionId: id, verdict: score >= 0.5 ? "approve" : "reject", score, missing }] };
}

/** Deterministic stand-in, so everything runs offline and in CI. It proves nothing about model quality. */
export class MockProvider implements LlmProvider {
  readonly id = "mock";

  async complete<T>({ name, user, schema }: LlmRequest<T>): Promise<LlmResult<T>> {
    const body = name.startsWith("check:") ? checkResponse(user) : name === "plan" ? planResponse(user) : gradeResponse(user);
    return { value: schema.parse(body), inputTokens: Math.ceil(user.length / 4), outputTokens: 50 };
  }
