import { fileURLToPath } from "node:url";
import { Answer, ReviewRequest, type Review } from "@viva/contracts";
import {
  appendAttestations,
  computeFog,
  entireSource,
  GeminiProvider,
  grepBlastRadius,
  loadChecks,
  loadFogFiles,
  MockProvider,
  readLedger,
  skipWithDebt,
  startReview,
  submitAnswers,
  type LlmProvider,
} from "@viva/engine";
import { Hono } from "hono";
import { z } from "zod";

export function createProvider(env: NodeJS.ProcessEnv = process.env): LlmProvider {
  if (env.VIVA_LLM === "gemini") {
    if (!env.GEMINI_API_KEY || !env.GEMINI_MODEL) throw new Error("set GEMINI_API_KEY and GEMINI_MODEL");
    return new GeminiProvider(env.GEMINI_API_KEY, env.GEMINI_MODEL, env.GEMINI_FALLBACK_MODEL);
  }
  return new MockProvider();
}

const CHECKS_DIR = fileURLToPath(new URL("../../../checks", import.meta.url));

/**
 * The daemon only tracks reviews and serves the UI. Reviews stay on this
 * machine, and only attestations leave it, inside git notes.
 */
export function createApp(llm: LlmProvider = createProvider()) {
  const reviews = new Map<string, Review>();
  const app = new Hono();

  app.get("/v1/health", (c) => c.json({ ok: true, llm: llm.id }));

  app.post("/v1/reviews", async (c) => {
    const request = ReviewRequest.parse(await c.req.json());
    const review = await startReview(request, {
      llm,
      checks: await loadChecks(CHECKS_DIR),
      session: entireSource,
      blast: grepBlastRadius,
      ledger: await readLedger(request.repoPath),
    });
    reviews.set(review.id, review);
    return c.json(review);
  });

  app.get("/v1/reviews", (c) => c.json([...reviews.values()].reverse()));

  app.get("/v1/reviews/:id", (c) => {
    const review = reviews.get(c.req.param("id"));
    return review ? c.json(review) : c.json({ error: "not found" }, 404);
  });

  app.post("/v1/reviews/:id/answers", async (c) => {
    const current = reviews.get(c.req.param("id"));
    if (!current) return c.json({ error: "not found" }, 404);
    const answers = z.array(Answer).parse(await c.req.json());
    const { review, attestations } = await submitAnswers(current, answers, { llm });
    reviews.set(review.id, review);
    await appendAttestations(review.request.repoPath, review.request.head, attestations);
    return c.json(review);
  });

  app.post("/v1/reviews/:id/skip", (c) => {
    const current = reviews.get(c.req.param("id"));
    if (!current) return c.json({ error: "not found" }, 404);
    const review = skipWithDebt(current);
    reviews.set(review.id, review);
    return c.json(review);
  });

  app.get("/v1/fog", async (c) => {
    const repoPath = c.req.query("repo") ?? process.cwd();
    return c.json(computeFog(await loadFogFiles(repoPath), await readLedger(repoPath), new Date()));
  });

  app.onError((error, c) => {
    console.error(error);
    return c.json({ error: error.message }, 500);
  });

  return app;
}
import { serve } from "@hono/node-server";
import { createApp } from "./app.js";

const port = Number(process.env.VIVA_PORT ?? 4317);
serve({ fetch: createApp().fetch, port, hostname: "127.0.0.1" }, () => {
  console.log(`vivad listening on http://127.0.0.1:${port}`);
});
import { execFileSync } from "node:child_process";
import { chmodSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Review } from "@viva/contracts";
import { allowsPush } from "@viva/engine";

const PORT = process.env.VIVA_PORT ?? "4317";
const API = `http://127.0.0.1:${PORT}/v1`;
const WEB = process.env.VIVA_WEB ?? "http://localhost:5173";
const POLL_MS = 1000;
const EXAM_TIMEOUT_MS = 10 * 60 * 1000;
const MARKER = "# viva gate";

const VIVA_ROOT = resolve(fileURLToPath(new URL("../../..", import.meta.url))).replaceAll("\\", "/");
/** The repo being pushed. Set by the hook, as pnpm --dir changes the working directory. */
const REPO = process.env.VIVA_REPO ?? process.cwd();

const git = (...args: string[]) => execFileSync("git", args, { cwd: REPO, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();

function pushBase(): string {
  for (const ref of ["@{upstream}", "origin/main", "main"]) {
    try {
      return git("merge-base", ref, "HEAD");
    } catch {
      // Try the next candidate.
    }
  }
  return "HEAD~1";
}

async function gate(): Promise<number> {
  const request = {
    repoPath: git("rev-parse", "--show-toplevel"),
    base: pushBase(),
    head: git("rev-parse", "HEAD"),
    person: git("config", "user.name"),
  };

  let review: Review;
  try {
    const response = await fetch(`${API}/reviews`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(request),
    });
    if (!response.ok) throw new Error(`vivad returned ${response.status}`);
    review = Review.parse(await response.json());
  } catch (error) {
    // Fail open: a broken or absent daemon must never stop a push.
    console.warn(`viva: skipped, daemon unavailable (${(error as Error).message})`);
    return 0;
  }

  if (review.stage === "awaiting-exam") {
    console.log(`viva: this push needs a viva: ${WEB}/?review=${review.id}`);
    const deadline = Date.now() + EXAM_TIMEOUT_MS;
    while (review.stage !== "done" && Date.now() < deadline) {
      await new Promise((resolve) => setTimeout(resolve, POLL_MS));
      review = Review.parse(await (await fetch(`${API}/reviews/${review.id}`)).json());
    }
  }

  if (!review.gate) {
    console.error("viva: exam timed out, push blocked");
    return 1;
  }
